import{_ as e,o as a,c as l,a2 as d}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"即時解答與關鍵字擴充功能","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/instant-answers.md","filePath":"zh-TW/user-guide/instant-answers.md","lastUpdated":1788085660000}'),o={name:"zh-TW/user-guide/instant-answers.md"};function s(n,t,i,r,c,g){return a(),l("div",null,[...t[0]||(t[0]=[d(`<h1 id="即時解答與關鍵字擴充功能" tabindex="-1">即時解答與關鍵字擴充功能 <a class="header-anchor" href="#即時解答與關鍵字擴充功能" aria-label="Permalink to &quot;即時解答與關鍵字擴充功能&quot;">​</a></h1><p>除了本機檔案檢索之外，Lertaro 還內建了一系列強大的即時計算、系統工具與關鍵字擴充外掛模組。無需等待檔案檢索，輸入對應指令即可即刻得到答案或觸發專業功能。</p><h2 id="_1-始終生效的即時解答" tabindex="-1">1. 始終生效的即時解答 <a class="header-anchor" href="#_1-始終生效的即時解答" aria-label="Permalink to &quot;1. 始終生效的即時解答&quot;">​</a></h2><p>無需輸入任何前置關鍵字，只要輸入的文字符合特定模式即可立即觸發：</p><h3 id="計算機與進位制轉換" tabindex="-1">計算機與進位制轉換 <a class="header-anchor" href="#計算機與進位制轉換" aria-label="Permalink to &quot;計算機與進位制轉換&quot;">​</a></h3><p>直接在搜尋框中輸入數學運算式，計算結果將在第一行即時呈現。按下 <code>Enter</code> 鍵即可將計算結果複製到剪貼簿：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span>
<span class="line"><span>100 * (1 - 0.15)</span></span></code></pre></div><p>支援常見的進位制轉換表達：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span>
<span class="line"><span>101010 to bin</span></span></code></pre></div><h3 id="環境變數展開與查詢" tabindex="-1">環境變數展開與查詢 <a class="header-anchor" href="#環境變數展開與查詢" aria-label="Permalink to &quot;環境變數展開與查詢&quot;">​</a></h3><ul><li><strong>精準展開變數</strong>：輸入 <code>%NAME%</code>（如 <code>%PATH%</code>、<code>%APPDATA%</code>）可直接檢視變數值。對於包含多個路徑的變數（如 <code>PATH</code>），Lertaro 會自動將其拆分為清晰的逐行清單，便於檢查環境設定。</li><li><strong>模糊搜尋變數</strong>：輸入 <code>%</code> 加上關鍵字（如 <code>%temp</code>）可模糊搜尋所有名稱中包含該關鍵字的系統與使用者環境變數。</li></ul><h3 id="快捷執行命令" tabindex="-1">快捷執行命令 <a class="header-anchor" href="#快捷執行命令" aria-label="Permalink to &quot;快捷執行命令&quot;">​</a></h3><p>無需先開啟終端機視窗，直接在搜尋框中輸入：</p><ul><li><code>#&lt;命令&gt;</code>：開啟命令提示字元視窗並<strong>以系統管理員權限</strong>執行該命令（例如 <code>#sfc /scannow</code> 或 <code>#net start Lertaro.Service</code>）。</li><li><code>$&lt;命令&gt;</code>：開啟命令提示字元視窗以<strong>目前一般使用者權限</strong>執行該命令（例如 <code>$ping 1.1.1.1</code> 或 <code>$ipconfig /all</code>）。</li></ul><h3 id="網址直達" tabindex="-1">網址直達 <a class="header-anchor" href="#網址直達" aria-label="Permalink to &quot;網址直達&quot;">​</a></h3><p>直接輸入或貼上以 <code>http://</code> 或 <code>https://</code> 開頭的完整網址，按下 <code>Enter</code> 即可立即在預設瀏覽器中開啟該頁面。當輸入沒有搜尋結果且以裸域名開頭時，快速搜尋視窗會自動填入 <code>https://</code> 並將游標移動到文字末尾；已經包含協定的輸入不會被修改。</p><h3 id="快速搜尋視窗匯入剪貼簿文字" tabindex="-1">快速搜尋視窗匯入剪貼簿文字 <a class="header-anchor" href="#快速搜尋視窗匯入剪貼簿文字" aria-label="Permalink to &quot;快速搜尋視窗匯入剪貼簿文字&quot;">​</a></h3><p>快速搜尋視窗在沒有預填內容的情況下被呼叫時，如果剪貼簿文字不為空且不同於該視窗上一次匯入的剪貼簿內容，就會自動填入並全選文字。相同內容不會重複匯入，從 URI 或完整搜尋視窗返回時的預填內容也不會被覆蓋。</p><h2 id="_2-關鍵字觸發功能-內建外掛模組" tabindex="-1">2. 關鍵字觸發功能（內建外掛模組） <a class="header-anchor" href="#_2-關鍵字觸發功能-內建外掛模組" aria-label="Permalink to &quot;2. 關鍵字觸發功能（內建外掛模組）&quot;">​</a></h2><p>透過輸入簡短的<strong>觸發關鍵字 + 空格</strong>，再輸入實際查詢內容，即可呼叫專項外掛模組能力。各關鍵字均可在<a href="./settings/plugins.html"><strong>設定 → 外掛模組</strong></a>中自訂修改。</p><table tabindex="0"><thead><tr><th style="text-align:left;">預設關鍵字</th><th style="text-align:left;">外掛模組名稱</th><th style="text-align:left;">功能說明與使用場景</th><th style="text-align:left;">典型使用範例</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ps</code></td><td style="text-align:left;"><strong>處理程序管理</strong></td><td style="text-align:left;">按處理程序名稱、PID 或視窗標題搜尋執行中的處理程序（支援拼音），按 Enter 一鍵結束處理程序。</td><td style="text-align:left;"><code>ps chrome</code> 或 <code>ps 1234</code></td></tr><tr><td style="text-align:left;"><code>win</code></td><td style="text-align:left;"><strong>視窗切換器</strong></td><td style="text-align:left;">搜尋並即時切換到目前開啟的應用程式視窗，支援背景即時擷取視窗縮圖。</td><td style="text-align:left;"><code>win code</code> 或 <code>win 瀏覽器</code></td></tr><tr><td style="text-align:left;"><code>bm</code></td><td style="text-align:left;"><strong>瀏覽器資料</strong></td><td style="text-align:left;">搜尋 Chrome、Edge、Firefox 等瀏覽器的書籤與歷史造訪記錄（書籤與歷史可獨立開關）。</td><td style="text-align:left;"><code>bm github</code></td></tr><tr><td style="text-align:left;"><code>set</code></td><td style="text-align:left;"><strong>設定搜尋</strong></td><td style="text-align:left;">模糊搜尋 Lertaro 自身的所有設定選項，選取即可直接跳轉到對應設定頁並反白該項。</td><td style="text-align:left;"><code>set 快速鍵</code> 或 <code>set 模糊</code></td></tr><tr><td style="text-align:left;"><code>flow</code></td><td style="text-align:left;"><strong>Flow 外掛模組橋接</strong></td><td style="text-align:left;">列出所有已載入的 Flow.Launcher 外掛模組及其觸發詞，支援無縫呼叫 Flow 社群生態。</td><td style="text-align:left;"><code>flow</code></td></tr></tbody></table><h2 id="_3-網頁搜尋快捷引擎" tabindex="-1">3. 網頁搜尋快捷引擎 <a class="header-anchor" href="#_3-網頁搜尋快捷引擎" aria-label="Permalink to &quot;3. 網頁搜尋快捷引擎&quot;">​</a></h2><p>網頁搜尋外掛模組內建了主流搜尋引擎快捷方式，輸入對應前綴並跟隨關鍵字即可一鍵拉起瀏覽器搜尋：</p><table tabindex="0"><thead><tr><th style="text-align:left;">快捷詞</th><th style="text-align:left;">對應搜尋引擎</th><th style="text-align:left;">範例</th><th style="text-align:left;">說明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>bd</code></td><td style="text-align:left;">百度 (Baidu)</td><td style="text-align:left;"><code>bd 深度學習</code></td><td style="text-align:left;">在百度中搜尋關鍵字</td></tr><tr><td style="text-align:left;"><code>g</code></td><td style="text-align:left;">谷歌 (Google)</td><td style="text-align:left;"><code>g lertaro github</code></td><td style="text-align:left;">在 Google 中搜尋關鍵字</td></tr><tr><td style="text-align:left;"><code>bing</code></td><td style="text-align:left;">必應 (Bing)</td><td style="text-align:left;"><code>bing 微軟文件</code></td><td style="text-align:left;">在 Bing 中搜尋關鍵字</td></tr><tr><td style="text-align:left;"><code>gh</code></td><td style="text-align:left;">GitHub</td><td style="text-align:left;"><code>gh Lertaro</code></td><td style="text-align:left;">直接在 GitHub 存放庫中搜尋</td></tr><tr><td style="text-align:left;"><code>wiki</code></td><td style="text-align:left;">維基百科 (Wikipedia)</td><td style="text-align:left;"><code>wiki 量子力學</code></td><td style="text-align:left;">在維基百科中查閱條目</td></tr><tr><td style="text-align:left;"><code>yt</code></td><td style="text-align:left;">YouTube</td><td style="text-align:left;"><code>yt lofi hip hop</code></td><td style="text-align:left;">在 YouTube 中搜尋影片</td></tr></tbody></table><p>你可以在<strong>設定 → 外掛模組 → 網頁搜尋 → 設定</strong>中自由新增、修改或刪除搜尋引擎與自訂 URL 範本。</p><h2 id="_4-即時翻譯" tabindex="-1">4. 即時翻譯 <a class="header-anchor" href="#_4-即時翻譯" aria-label="Permalink to &quot;4. 即時翻譯&quot;">​</a></h2><p>輸入預設觸發詞 <code>tr</code> 並在其後輸入待翻譯的內容，即可自動翻譯為 Lertaro 目前所選的介面語言：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tr Hello, how are you today?</span></span></code></pre></div><ul><li>翻譯結果隨輸入非同步呈現，按 <code>Enter</code> 鍵即可一鍵複製譯文。</li><li>可在<strong>設定 → 外掛模組 → 翻譯 → 設定</strong>中變更觸發詞或檢視連線狀態。</li></ul><h2 id="_5-檔案篩選器" tabindex="-1">5. 檔案篩選器 <a class="header-anchor" href="#_5-檔案篩選器" aria-label="Permalink to &quot;5. 檔案篩選器&quot;">​</a></h2><p>在<strong>設定 → 外掛模組 → 檔案篩選器 → 設定</strong>中，你可以為特定目錄和副檔名建立專屬篩選器規則：</p><ul><li><strong>指定監控目錄</strong>：遞迴掃描指定工作目錄（如 <code>D:\\Engineering\\Drawings</code>）。</li><li><strong>指定比對規則</strong>：例如 <code>*.dwg;*.dxf</code> 或 <code>*.pdf;*.docx</code>（不影響子資料夾收錄）。</li><li><strong>設定觸發關鍵字</strong>：為該規則綁定專屬前綴（如 <code>cad</code> 或 <code>doc</code>），輸入 <code>cad 零件圖</code> 即可實現特定業務資料的精準隔離搜尋。</li></ul><h2 id="_6-自訂命令" tabindex="-1">6. 自訂命令 <a class="header-anchor" href="#_6-自訂命令" aria-label="Permalink to &quot;6. 自訂命令&quot;">​</a></h2><p>在<strong>設定 → 外掛模組 → 自訂命令 → 設定</strong>中，你可以將任意複雜的命令列工具、指令碼或外部應用程式包裝為一個簡短的啟動命令：</p><ul><li><strong>參數預留位置</strong>：支援位置預留位置 <code>%s1</code>、<code>%s2</code>……（對應以空格分隔的參數）以及全文預留位置 <code>%s</code>（代表關鍵字後的所有輸入文字）。</li><li><strong>快速導覽整合</strong>：勾選「在快速導覽中顯示」後，該命令會直接作為功能表項出現在<a href="./hotkeys.html#3-快速導覽滑鼠觸發"><strong>快速導覽</strong></a>中，支援使用 <code>/</code> 建立多級子功能表分類（如 <code>開發工具/重啟服務</code>）。</li></ul>`,35)])])}const x=e(o,[["render",s]]);export{p as __pageData,x as default};
